import lombok.Builder;
import lombok.Data;

@Data
@Builder
public class AISummaryDTO {
    // 1. Énergie
    private double currentMonthEnergy;    // Consommation d'énergie du mois en cours
    private double lastMonthEnergy;       // Consommation du mois précédent (pour comparaison)
    private String energyTrend;           // Tendance (ex: "+10%" ou "-5%")

    // 2. Environnement
    private double totalCo2;              // Impact total carbone depuis le début (Lifetime)
    private double recyclingRate;         // Taux de recyclage en pourcentage

    // 3. Finance (Estimation)
    private double estimatedCost;         // Coût estimé pour le mois en cours
}

@Aggregation(pipeline = {
        "{ $match: { dataType: ?0, timestamp: { $gte: ?1, $lte: ?2 } } }", // Filtrer par type et date
        "{ $group: { _id: null, total: { $sum: '$value' } } }"             // Additionner la colonne 'value'
    })
    Double sumValueByDataTypeAndDateRange(String dataType, LocalDateTime start, LocalDateTime end);

public AISummaryDTO generateDashboardStats() {
        // 1. Définition des plages de dates
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime startOfCurrentMonth = now.withDayOfMonth(1).withHour(0).withMinute(0);
        LocalDateTime startOfLastMonth = startOfCurrentMonth.minusMonths(1);
        LocalDateTime endOfLastMonth = startOfCurrentMonth.minusSeconds(1);

        // 2. Calcul de l'énergie (Mois actuel vs Mois précédent)
        Double currentEnergy = repository.sumValueByDataTypeAndDateRange("ENERGY", startOfCurrentMonth, now);
        Double lastEnergy = repository.sumValueByDataTypeAndDateRange("ENERGY", startOfLastMonth, endOfLastMonth);

        // Gestion des valeurs nulles (si aucune donnée en base)
        double current = (currentEnergy != null) ? currentEnergy : 0.0;
        double last = (lastEnergy != null) ? lastEnergy : 0.0;

        // 3. Calcul de la tendance énergétique (Trend)
        String trend;
        if (last == 0) {
            trend = "0%"; // Évite la division par zéro
        } else {
            double percentChange = ((current - last) / last) * 100;
            // Formatage: ajoute un "+" si positif (ex: "+12.5%")
            trend = (percentChange > 0 ? "+" : "") + String.format("%.1f", percentChange) + "%";
        }

        // 4. Récupération de l'impact CO2 total (Global)
        Double co2 = repository.sumTotalCo2Impact();
        double totalCo2 = (co2 != null) ? co2 : 0.0;

        // 5. Calcul du taux de recyclage (Mois en cours)
        long totalWaste = repository.countByDataTypeAndTimestampAfter("WASTE", startOfCurrentMonth);
        long recycledWaste = repository.countByDataTypeAndWasteTypeAndTimestampAfter("WASTE", "recyclable", startOfCurrentMonth);

        // Calcul du pourcentage (éviter division par zéro)
        double recyclingRate = (totalWaste > 0) ? ((double) recycledWaste / totalWaste) * 100 : 0.0;

        // 6. Estimation financière (Coût)
        double cost = current * ENERGY_COST_PER_KWH;

        // 7. Construction et retour de l'objet DTO
        return AISummaryDTO.builder()
                .currentMonthEnergy(current)
                .lastMonthEnergy(last)
                .energyTrend(trend)
                .totalCo2(totalCo2)
                .recyclingRate(recyclingRate)
                .estimatedCost(cost)
                .build();
    }

