@Service
@RequiredArgsConstructor
public class AIService {

    @Value("${ai.deepseek.api-key:sk-435906190b884e668ac1e16c72634c17}")
    private String apiKey;

    @Value("${ai.deepseek.base-url:https://api.deepseek.com/chat/completions}")
    private String apiUrl;

    @Value("${ai.deepseek.model:deepseek-chat}")
    private String model;

    private final SmartDataRepository repository;
    private final RestTemplate restTemplate = new RestTemplate();

    // 1. برومبت ذكي كيقبل أي داتا (JSON)
    private static final String SYSTEM_PROMPT_TEMPLATE = """
    Tu es l'assistant IA de 'GreenTech Innovators'.

    🚨 RÔLE : Tu es un expert en analyse de données énergétiques.

    📊 VOICI LES DONNÉES DE L'ENTREPRISE (MOIS EN COURS) :
    %s

    📝 INSTRUCTIONS :
    1. Utilise CES données pour répondre. Ne jamais inventer de chiffres.
    2. Si l'utilisateur demande le "Total Gaz", regarde dans le JSON sous 'GAS'.
    3. Si l'utilisateur demande le "Transport", regarde 'TRANSPORT'.
    4. Pour l'électricité, commente la tendance et le coût.
    5. Sois professionnel, concis et utilise des émojis.

    Si la question n'a rien à voir avec ces données (ex: sport, cuisine), refuse poliment.
    """;

    public String askAI(String userMessage, List<Map<String, String>> history) {
        // 1. جمع الداتا كاملة من DB
        String globalContext = getGlobalContextJson();

        // 2. حطها فالـ Prompt
        String dynamicPrompt = String.format(SYSTEM_PROMPT_TEMPLATE, globalContext);

        // 3. صيفط لـ DeepSeek
        return callDeepSeek(dynamicPrompt, userMessage, history);
    }

    // 🧠 هاد الميطود هي العقل: كتجمع كلشي فـ نص واحد
    private String getGlobalContextJson() {
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime startOfMonth = now.withDayOfMonth(1).withHour(0).withMinute(0);

        // A. جيب الاستهلاك ديال كل نوع
        double elec = getSum("ENERGY", startOfMonth, now);
        double gas = getSum("GAS", startOfMonth, now);
        double transport = getSum("TRANSPORT", startOfMonth, now);
        double waste = getSum("WASTE", startOfMonth, now);

        // B. جيب أكبر مستهلك للضو
        String topConsumer = "Inconnu";
        List<TopConsumerStats> tops = repository.findTopConsumer(startOfMonth);
        if (!tops.isEmpty()) topConsumer = tops.get(0).getLocation();

        // C. صاوب JSON String بيدك (باش يكون ساهل ومفهوم للـ AI)
        return String.format("""
            {
                "ELECTRICITE": {
                    "Consommation": "%.2f kWh",
                    "Coût_Estime": "%.2f MAD",
                    "Top_Consommateur": "%s"
                },
                "GAZ": {
                    "Consommation": "%.2f m3",
                    "Coût_Estime": "%.2f MAD"
                },
                "TRANSPORT": {
                    "Distance_Parcourue": "%.2f km",
                    "Carburant_Estime": "%.2f Litres"
                },
                "DECHETS": {
                    "Total_Genere": "%.2f kg"
                }
            }
            """, 
            elec, (elec * 1.2), topConsumer, // Elec info
            gas, (gas * 10.5),               // Gas info (Ex: 10.5dh/m3)
            transport, (transport * 0.08),   // Transport info
            waste                            // Waste info
        );
    }

    // Helper باش نتفاداو Null
    private double getSum(String type, LocalDateTime start, LocalDateTime end) {
        Double val = repository.sumValueByDataTypeAndDateRange(type, start, end);
        return val != null ? val : 0.0;
    }

    // Helper للاتصال بـ API
    private String callDeepSeek(String systemPrompt, String userMsg, List<Map<String, String>> history) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.setBearerAuth(apiKey);

        Map<String, Object> body = new HashMap<>();
        body.put("model", model);
        body.put("stream", false);

        List<Map<String, String>> messages = new ArrayList<>();
        messages.add(Map.of("role", "system", "content", systemPrompt));

        if (history != null) {
            for (Map<String, String> msg : history) {
                messages.add(Map.of("role", msg.get("role"), "content", msg.get("content")));
            }
        }

        messages.add(Map.of("role", "user", "content", userMsg));
        body.put("messages", messages);

        try {
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(body, headers);
            Map<String, Object> response = restTemplate.postForObject(apiUrl, entity, Map.class);

            if (response != null && response.containsKey("choices")) {
                List<Map<String, Object>> choices = (List<Map<String, Object>>) response.get("choices");
                if (!choices.isEmpty()) {
                    Map<String, Object> messageObj = (Map<String, Object>) choices.get(0).get("message");
                    return (String) messageObj.get("content");
                }
            }
            return "Désolé, pas de réponse.";
        } catch (Exception e) {
            return "Erreur API: " + e.getMessage();
        }
    }

    // خلي generateDashboardStats للـ Frontend (Cards)
    // ...
}

