private List<Double> getHistoryData(List<DailyStat> dbStats) {
        Map<String, Double> statsMap = new HashMap<>();
        for (DailyStat stat : dbStats) {
            statsMap.put(stat.getDate(), stat.getTotal());
        }

        List<Double> history = new ArrayList<>();
        // نبدأ من 6 أيام قبل (يعني 7 أيام بالمجموع مع اليوم)
        LocalDateTime dateIter = LocalDateTime.now().minusDays(6);

        for (int i = 0; i < 7; i++) {
            String key = dateIter.toLocalDate().toString(); // YYYY-MM-DD
            // إلا كان النهار كاين خودو، إلا لا حط 0.0
            history.add(statsMap.getOrDefault(key, 0.0));
            dateIter = dateIter.plusDays(1);
        }
        return history;
    }

private void seedEnergyData() {
        List<Energy> energyData = new ArrayList<>();
        String[] locations = {"production", "Bureaux", "Entrepôt", "Cafeteria"};

        for (int day = 30; day >= 0; day--) {
            for (int hour = 0; hour < 24; hour++) {
                for (String location : locations) {
                    // ✅ Khlaqna Energy object, machi SmartData
                    Energy data = new Energy();
                    data.setValue(generateEnergyValue(hour));
                    data.setUnit("kWh");
                    data.setSensorId("ESP32-ELEC-" + location.substring(0, 3).toUpperCase());
                    data.setLocation(location);
                    data.setTimestamp(LocalDateTime.now().minusDays(day).minusHours(24 - hour));
                    data.setStatus("NORMAL");

                    energyData.add(data);
                }
            }
        }
        energyRepository.saveAll(energyData);
        System.out.println("⚡ Energy data seeded: " + energyData.size() + " records");
    }

