    // ✅ FIX 1: MONTHLY SUM (Même المشكل ديال المقارنة)
    @Aggregation(pipeline = {
            // 1. (جديد) كنحولو createdAt (String) لـ dateObj (Date)
            "{ '$addFields': { 'dateObj': { $dateFromString: { dateString: '$createdAt' } } } }",

            // 2. Match كيستعمل dateObj باش يقارن مع التاريخ اللي جاي من Java
            "{ '$match': { 'dateObj': { '$gte': ?0 } } }",
            "{ '$group': { '_id': null, 'total': { '$sum': '$consumedGas' } } }"
    })
    Double sumValueByCreatedAtAfter(LocalDateTime date);


    // ✅ FIX 2: 7-DAY HISTORY (كانت هادي هي اللي كتفشل و كترجع Array خاوي)
    @Aggregation(pipeline = {
            // 1. (جديد) تحويل createdAt (String) إلى dateObj (Date)
            "{ '$addFields': { 'dateObj': { $dateFromString: { dateString: '$createdAt' } } } }",

            // 2. Match كيستعمل dateObj باش يقارن
            "{ '$match': { 'dateObj': { '$gte': ?0 } } }", 

            // 3. Group and Sort (كنستعملوا dateObj باش نجمعو)
            "{ '$group': { '_id': { $dateToString: { format: '%Y-%m-%d', date: '$dateObj' } }, 'total': { '$sum': '$consumedGas' } } }",
            "{ '$sort': { '_id': 1 } }"
    })
    List<DailyStat> getLast7DaysStats(LocalDateTime startDate);
